// The levels and the tile generator.
//
// Tiles are generated by simulating crabs eating the picture the way the game
// does: in from the frame, always the nearest reachable piece of their colour,
// walking only over what is already eaten. Each tile is one such run, so the
// dealt order clears the picture; dealing tiles out of order is the player's risk.

import type { Board } from './segment';
import { Nav } from './nav';
import { PICTURES, type Picture } from './pictures';

export interface LevelDef {
  picture: Picture;
  /** Piece size in picture pixels: smaller = more pieces. */
  cell: number;
  slots: number;
  columns: number;
  /** Tile sizes, rounded to 5. */
  minTile: number;
  maxTile: number;
  /** 0 = tiles are dealt in solving order, 1 = heavily shuffled, over a window of up to 4 rows. */
  shuffle: number;
  difficulty: 'easy' | 'normal' | 'hard';
  seed: number;
  /** Box blockers, see applyBlockers. */
  blockers?: Blockers;
}

/**
 * - mystery: share of boxes (not in the starting front row) whose colour stays hidden until tapped
 * - ice: frozen boxes, each needing iceMin..iceMax other boxes sent before it thaws
 * - chains: pairs of side-by-side boxes that only leave together (both at the front, two free slots)
 */
export interface Blockers {
  mystery?: number;
  ice?: number;
  iceMin?: number;
  iceMax?: number;
  chains?: number;
}

