export function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface TileDef {
  cls: number;
  value: number;
  /** Unique within the level; chains refer to it. */
  id?: number;
  hidden?: boolean;
  /** Boxes still to send before this one thaws (0 / undefined = free). */
  ice?: number;
  /** id of the chained partner. */
  link?: number;
}

/** The tile columns, front first. `nav` is left as it was (all closed). */
export function dealTiles(board: Board, def: LevelDef, nav: Nav): TileDef[][] {
  const rand = rng(def.seed);
  const { pieces } = board;
  const eaten = new Uint8Array(pieces.length);
  // crabs enter at the middle of the frame's bottom edge
  const start = nav.cell(Math.floor(nav.cols / 2), nav.rows);

  const left = [...board.counts];
  const seq: TileDef[] = [];
  let done = 0;
  let last = -1;
  while (done < pieces.length) {
    // a box starts on a colour with enough within reach, so no box is a crumb of 1-4
    const reach = new Map<number, number>();
    for (const p of nav.frontier(start)) if (!eaten[p]) reach.set(pieces[p].cls, (reach.get(pieces[p].cls) ?? 0) + 1);
    const all = [...reach.keys()];
    const roomy = all.filter((c) => reach.get(c)! >= Math.min(5, left[c]));
    const classes = roomy.length ? roomy : all;
    if (!classes.length) break; // nothing left in reach: never spin
    const pool = classes.length > 1 ? classes.filter((c) => c !== last) : classes;
    const cls = pool[Math.floor(rand() * pool.length)];
    let want = Math.round((def.minTile + rand() * (def.maxTile - def.minTile)) / 5) * 5;
    // never leave a crumb of a colour behind
    if (left[cls] - want < def.minTile) want = left[cls];
    let took = 0;
    while (took < want) {
      const route = nav.nearest(start, (p) => !eaten[p] && pieces[p].cls === cls);
      if (!route) break;
      eaten[route.piece] = 1;
      nav.clear(route.piece);
      took++;
    }
    done += took;
    left[cls] -= took;
    // a short run joins the previous tile of the same colour when they are back to back
    const prev = seq[seq.length - 1];
    if (prev && prev.cls === cls) prev.value += took;
    else seq.push({ cls, value: took });
    last = cls;
  }
  nav.reset();

  // a leftover crumb (under 5) rides along with a nearby box of its colour, which eats
  // those pieces first — but only where that box stays a sensible size
  for (let i = 0; i < seq.length; i++) {
    if (seq[i].value >= 5) continue;
    const cap = def.maxTile + 10;
    let j = seq.findIndex((t, k) => k > i && t.cls === seq[i].cls && t.value + seq[i].value <= cap);
    if (j < 0) j = seq.findLastIndex((t, k) => k < i && t.cls === seq[i].cls && t.value + seq[i].value <= cap);
    if (j < 0) continue;
    seq[j].value += seq[i].value;
    seq.splice(i--, 1);
  }

  // light shuffle inside a sliding window: later tiles may jump a little forward
  const window = Math.round(def.columns * (1 + def.shuffle * 3));
  for (let i = 0; i < seq.length; i++) {
    if (rand() >= def.shuffle) continue;
    const j = Math.min(seq.length - 1, i + 1 + Math.floor(rand() * window));
    [seq[i], seq[j]] = [seq[j], seq[i]];
  }

  const cols: TileDef[][] = Array.from({ length: def.columns }, () => []);
  seq.forEach((t, i) => cols[i % def.columns].push(t));
  seq.forEach((t, i) => { t.id = i; });
  if (def.blockers) applyBlockers(cols, def.blockers, rand);
  return cols;
}

/** Places a level's blockers on the dealt columns. */
function applyBlockers(cols: TileDef[][], b: Blockers, rand: () => number): void {
  const pickOf = <T>(list: T[]) => list.splice(Math.floor(rand() * list.length), 1)[0];
  // chains: two boxes in the same row of neighbouring columns
  const pairs: [TileDef, TileDef][] = [];
  for (let j = 0; j + 1 < cols.length; j++) {
    for (let k = 1; k < Math.min(cols[j].length, cols[j + 1].length, 6); k++) pairs.push([cols[j][k], cols[j + 1][k]]);
  }
  for (let n = 0; n < (b.chains ?? 0) && pairs.length; n++) {
    const [a, c] = pickOf(pairs);
    if (a.link !== undefined || c.link !== undefined) { n--; continue; }
    a.link = c.id;
    c.link = a.id;
  }
  // ice: in the two rows on screen, where it bites; never more than half the front row
  const iceable: { t: TileDef; k: number }[] = [];
  cols.forEach((col) => col.forEach((t, k) => { if (k < 2 && t.link === undefined) iceable.push({ t, k }); }));
  let frontIce = 0;
  const lo = b.iceMin ?? 3, hi = b.iceMax ?? 5;
  for (let n = 0; n < (b.ice ?? 0) && iceable.length; n++) {
    const { t, k } = pickOf(iceable);
    if (k === 0 && frontIce >= Math.floor(cols.length / 2)) { n--; continue; }
    if (k === 0) frontIce++;
    t.ice = lo + Math.floor(rand() * (hi - lo + 1));
  }
  // mystery: anywhere but the starting front row
  if (b.mystery) cols.forEach((col) => col.forEach((t, k) => { if (k > 0 && !t.ice && rand() < b.mystery!) t.hidden = true; }));
}
